SELECT 'profile' AS kind,count(*) AS inconsistent_rows FROM profiles p WHERE cardinality(p.domains)<>(SELECT count(*) FROM profile_domains j WHERE j.profile_id=p.id) OR EXISTS(SELECT 1 FROM profile_domains j JOIN domains d ON d.id=j.domain_id WHERE j.profile_id=p.id AND NOT(d.name=ANY(p.domains)))
UNION ALL SELECT 'project',count(*) FROM projects p WHERE cardinality(p.domains)<>(SELECT count(*) FROM project_domains j WHERE j.project_id=p.id) OR EXISTS(SELECT 1 FROM project_domains j JOIN domains d ON d.id=j.domain_id WHERE j.project_id=p.id AND NOT(d.name=ANY(p.domains)))
UNION ALL SELECT 'role',count(*) FROM project_roles p WHERE cardinality(p.domains)<>(SELECT count(*) FROM role_domains j WHERE j.role_id=p.id) OR EXISTS(SELECT 1 FROM role_domains j JOIN domains d ON d.id=j.domain_id WHERE j.role_id=p.id AND NOT(d.name=ANY(p.domains)));
